CREATE TYPE "AdminTeamRole" AS ENUM ('SUPER_ADMIN','OPERATIONS','FINANCE','MARKETING','MODERATOR');
CREATE TYPE "AdminNotificationSeverity" AS ENUM ('INFO','WARNING','CRITICAL');
CREATE TYPE "AdminNotificationCategory" AS ENUM ('ORDER','PAYMENT','STOCK','PAYOUT','KYC','PRODUCT','HAAT');
ALTER TABLE "admin_audit_logs" ADD COLUMN "permission" TEXT, ADD COLUMN "previous_state" JSONB, ADD COLUMN "next_state" JSONB;
CREATE TABLE "admin_memberships" ("id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"role" "AdminTeamRole" NOT NULL DEFAULT 'OPERATIONS',"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "admin_memberships_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "admin_memberships_user_id_key" ON "admin_memberships"("user_id"); CREATE INDEX "admin_memberships_role_is_active_idx" ON "admin_memberships"("role","is_active");
CREATE TABLE "admin_notifications" ("id" TEXT NOT NULL,"severity" "AdminNotificationSeverity" NOT NULL,"category" "AdminNotificationCategory" NOT NULL,"title" TEXT NOT NULL,"message" TEXT NOT NULL,"action_href" TEXT,"entity_type" TEXT,"entity_id" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expires_at" TIMESTAMP(3),CONSTRAINT "admin_notifications_pkey" PRIMARY KEY ("id")); CREATE INDEX "admin_notifications_created_at_severity_idx" ON "admin_notifications"("created_at","severity");
CREATE TABLE "admin_notification_reads" ("notification_id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"read_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "admin_notification_reads_pkey" PRIMARY KEY ("notification_id","user_id")); CREATE INDEX "admin_notification_reads_user_id_read_at_idx" ON "admin_notification_reads"("user_id","read_at");
CREATE TABLE "admin_action_reasons" ("id" TEXT NOT NULL,"actor_id" TEXT NOT NULL,"action" TEXT NOT NULL,"entity_type" TEXT NOT NULL,"entity_id" TEXT NOT NULL,"reason" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "admin_action_reasons_pkey" PRIMARY KEY ("id")); CREATE INDEX "admin_action_reasons_entity_type_entity_id_created_at_idx" ON "admin_action_reasons"("entity_type","entity_id","created_at");
ALTER TABLE "admin_memberships" ADD CONSTRAINT "admin_memberships_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "admin_notification_reads" ADD CONSTRAINT "admin_notification_reads_notification_id_fkey" FOREIGN KEY ("notification_id") REFERENCES "admin_notifications"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "admin_notification_reads" ADD CONSTRAINT "admin_notification_reads_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
INSERT INTO "admin_memberships" ("id","user_id","role","is_active","updated_at") SELECT 'adm_' || "id","id",'SUPER_ADMIN',true,CURRENT_TIMESTAMP FROM "users" WHERE "role"='ADMIN' ON CONFLICT ("user_id") DO NOTHING;
